#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 2; // tensor num for each queue

class KernelGruHiddenCopy {
public:
    __aicore__ inline KernelGruHiddenCopy() {}
    __aicore__ inline void Init(GM_ADDR h, GM_ADDR hn, uint32_t totalLength, uint32_t tileNum)
    {
        this->blockLength = totalLength / AscendC::GetBlockNum();
        this->tileNum = tileNum;
        this->tileLength = this->blockLength / tileNum / BUFFER_NUM;

        inGm.SetGlobalBuffer((__gm__ DTYPE_H *)h + this->blockLength * AscendC::GetBlockIdx(), this->blockLength);
        outGm.SetGlobalBuffer((__gm__ DTYPE_HN *)hn + this->blockLength * AscendC::GetBlockIdx(), this->blockLength);

        pipe.InitBuffer(inQueue, BUFFER_NUM, this->tileLength * sizeof(DTYPE_H));
        pipe.InitBuffer(outQueue, BUFFER_NUM, this->tileLength * sizeof(DTYPE_HN));
    }

    __aicore__ inline void Process()
    {
        int32_t loopCount = this->tileNum * BUFFER_NUM;
        for (int32_t i = 0; i < loopCount; i++) {
            CopyIn(i);
            Compute(i);
            CopyOut(i);
        }
    }

private:
    __aicore__ inline void CopyIn(int32_t progress)
    {
        AscendC::LocalTensor<DTYPE_H> hLocal = inQueue.AllocTensor<DTYPE_H>();
        AscendC::DataCopy(hLocal, inGm[progress * this->tileLength], this->tileLength);
        inQueue.EnQue(hLocal);
    }

    __aicore__ inline void Compute(int32_t)
    {
        AscendC::LocalTensor<DTYPE_H> hLocal = inQueue.DeQue<DTYPE_H>();
        AscendC::LocalTensor<DTYPE_HN> hnLocal = outQueue.AllocTensor<DTYPE_HN>();
        // Identity copy on UB
        AscendC::DataCopy(hnLocal, hLocal, this->tileLength);
        outQueue.EnQue<DTYPE_HN>(hnLocal);
        inQueue.FreeTensor(hLocal);
    }

    __aicore__ inline void CopyOut(int32_t progress)
    {
        AscendC::LocalTensor<DTYPE_HN> hnLocal = outQueue.DeQue<DTYPE_HN>();
        AscendC::DataCopy(outGm[progress * this->tileLength], hnLocal, this->tileLength);
        outQueue.FreeTensor(hnLocal);
    }

private:
    AscendC::TPipe pipe;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueue;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueue;
    AscendC::GlobalTensor<DTYPE_H> inGm;
    AscendC::GlobalTensor<DTYPE_HN> outGm;
    uint32_t blockLength;
    uint32_t tileNum;
    uint32_t tileLength;
};

extern "C" __global__ __aicore__ void gru_bidirectional_hidden_custom(GM_ADDR h, GM_ADDR hn, GM_ADDR workspace, GM_ADDR tiling) {
    GET_TILING_DATA(tiling_data, tiling);
    KernelGruHiddenCopy op;
    op.Init(h, hn, tiling_data.totalLength, tiling_data.tileNum);
    op.Process();
}
"""

